"""Render our grounded Markdown subset as escaped, printable HTML."""
from html import escape
from reports.grounded import report

def render_markdown(text):
    # Only headings, plain paragraphs, lists and tables generated by report().
    # No raw HTML, links, scripts or arbitrary Markdown extensions are evaluated.
    lines = text.splitlines(); output = []; index = 0
    while index < len(lines):
        line = lines[index]
        if not line.strip():
            index += 1; continue
        if line.startswith('# '):
            output.append('<h1>' + escape(line[2:]) + '</h1>'); index += 1
        elif line.startswith('## '):
            output.append('<h2>' + escape(line[3:]) + '</h2>'); index += 1
        elif line.startswith('|'):
            rows = []
            while index < len(lines) and lines[index].startswith('|'):
                cells = [x.strip() for x in lines[index].strip().strip('|').split('|')]
                if not all(set(x) <= set('-: ') for x in cells): rows.append(cells)
                index += 1
            if rows:
                head = '<thead><tr>' + ''.join('<th scope="col">'+escape(x)+'</th>' for x in rows[0]) + '</tr></thead>'
                body = '<tbody>' + ''.join('<tr>'+''.join('<td>'+escape(x)+'</td>' for x in row)+'</tr>' for row in rows[1:]) + '</tbody>'
                output.append('<table>'+head+body+'</table>')
        elif line.startswith('- '):
            items = []
            while index < len(lines) and lines[index].startswith('- '):
                items.append('<li>'+escape(lines[index][2:])+'</li>'); index += 1
            output.append('<ul>'+''.join(items)+'</ul>')
        else:
            output.append('<p>'+escape(line)+'</p>'); index += 1
    return ''.join(output)

def report_html(job):
    title = 'TRINETRA situation report · ' + str(job.get('id', ''))
    return ('<!doctype html><html lang="en"><head><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width,initial-scale=1">'
        '<title>'+escape(title)+'</title><style>'
        'body{max-width:960px;margin:32px auto;padding:24px;color:#172033;font:15px/1.55 system-ui,sans-serif}'
        'h1{font-size:28px;color:#075985}h2{font-size:19px;border-bottom:1px solid #cbd5e1;padding-bottom:6px;margin-top:28px}'
        'p,li,td{overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;margin:16px 0}'
        'th,td{padding:10px;border:1px solid #cbd5e1;text-align:left}th{background:#f1f5f9}'
        'button{padding:10px 18px;background:#075985;color:white;border:0;border-radius:6px;cursor:pointer}'
        '@page{size:A4;margin:16mm}@media print{body{margin:0;padding:0;font-size:10pt}button{display:none}'
        'h1,h2{break-after:avoid}tr{break-inside:avoid}thead{display:table-header-group}}'
        '</style></head><body><button onclick="window.print()">Print / PDF</button>'
        +render_markdown(report(job))+'</body></html>')
